// Usage: node tools/readme-examples.mjs [--options JSON] [--out DIR] [NAME ...]; needs target/release/layout-command
// (cargo build --release -p arqlet-runtime --bins). Without arguments it writes the README images; `--options` and `--out`
// draw variants elsewhere for a before-and-after comparison.
// Draws the example images in docs/assets/examples/ for the README: each example graph of benchmarks/datasets (generated by
// benchmarks/generate.py) is imported with the default options, turned into a scene by the engine, and painted by the
// SVG viewer of @arqlet/viewer into a standalone SVG file (the playground's dark canvas, xmlns). The viewer runs on a minimal DOM, as in
// packages/viewer/golden.test.mjs, so the images are exactly what the viewer draws.
import {readFileSync, writeFileSync, mkdirSync} from 'node:fs';
import {spawnSync} from 'node:child_process';
import {renderSvg} from '../packages/viewer/svg.js';

const ROOT = new URL('../', import.meta.url).pathname;
const COMMAND = process.env.ARQLET_LAYOUT_COMMAND ?? `${ROOT}target/release/layout-command`;
const args = process.argv.slice(2);
const option = (name, fallback) => {
  const i = args.indexOf(name);
  return i >= 0 ? args.splice(i, 2)[1] : fallback;
};
const OPTIONS = JSON.parse(option('--options', '{}'));
const OUT = option('--out', `${ROOT}docs/assets/examples`);
const ALL = [
  ['cloud-architecture', 'Layered containers with their own directions'],
  ['petri-net-shapes', 'An organic area with circles and boxes'],
  ['mixed-layouts', 'An organic root over layered containers'],
  ['state-tcp', 'A state machine with cycles and self-loops'],
];
const EXAMPLES = args.length ? args.map(name => ALL.find(([known]) => known === name) ?? [name, name]) : ALL;

class Element {
  constructor(tag) { this.tag = tag; this.children = []; this.attrs = {}; this.textContent = ''; }
  append(...items) { this.children.push(...items); }
  replaceChildren() { this.children = []; }
  setAttribute(k, v) { this.attrs[k] = v; }
}
const document = {createElementNS: (_, tag) => new Element(tag)};
const escape = s => String(s).replace(/&/g, '&amp;').replace(/"/g, '&quot;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
function markup(node) {
  if (!(node instanceof Element)) return '';
  const attrs = Object.entries(node.attrs).map(([k, v]) => ` ${k}="${escape(v)}"`).join('');
  const inner = (node.textContent ? escape(node.textContent) : '') + node.children.map(markup).join('');
  return inner ? `<${node.tag}${attrs}>${inner}</${node.tag}>` : `<${node.tag}${attrs}/>`;
}
function call(request) {
  const result = spawnSync(COMMAND, [], {input: JSON.stringify(request), encoding: 'utf8', maxBuffer: 1 << 28});
  if (result.status !== 0) throw new Error(result.stderr);
  const response = JSON.parse(result.stdout);
  if (!response.ok) throw new Error(response.error);
  return response;
}

mkdirSync(OUT, {recursive: true});
for (const [name, title] of EXAMPLES) {
  const raw = JSON.parse(readFileSync(`${ROOT}benchmarks/datasets/${name}.json`, 'utf8'));
  const graph = raw.graph ?? raw;
  const {snapshot} = call({op: 'import', graph, limit: graph.nodes.length, options: OPTIONS});
  const {scene} = call({op: 'scene', snapshot});
  const svg = new Element('svg');
  renderSvg(svg, scene, {document});
  svg.setAttribute('xmlns', 'http://www.w3.org/2000/svg');
  svg.setAttribute('role', 'img');
  const label = new Element('title');
  label.textContent = `${title} (${name}, laid out by Arqlet)`;
  svg.children.unshift(label);
  // The playground's dark canvas behind the viewer's dark nodes, so the image reads on light and dark pages alike.
  const [x, y, w, h] = (svg.attrs.viewBox ?? '0 0 0 0').split(' ').map(Number);
  const back = new Element('rect');
  Object.assign(back.attrs, {x, y, width: w, height: h, fill: '#0f1824'});
  svg.children.splice(1, 0, back);
  writeFileSync(`${OUT}/${name}.svg`, markup(svg).replace(/lw-arrow-\d+/g, 'lw-arrow') + '\n');
  console.log(name, `${svg.attrs.width}×${svg.attrs.height}`);
}
